Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "fold": [
        "Gasolina: sem tributos",
        "Gasolina: sem federais, ICMS dentro",
        "Gasolina: ICMS",
        "Gasolina: PIS/Cofins",
        "Gasolina: CIDE"
      ],
      "as": [
        "serie",
        "valor"
      ]
    },
    {
      "calculate": "isValid(datum.valor) ? datum.valor : 0",
      "as": "valor"
    },
    {
      "calculate": "datum.serie == ''Gasolina: sem tributos'' ? ''Sem tributos'' : datum.serie == ''Gasolina: sem federais, ICMS dentro'' ? ''Sem federais (ICMS dentro)'' : datum.serie == ''Gasolina: ICMS'' ? ''ICMS'' : datum.serie == ''Gasolina: PIS/Cofins'' ? ''PIS/Cofins'' : datum.serie == ''Gasolina: CIDE'' ? ''CIDE'' : ''''",
      "as": "Parcela"
    },
    {
      "calculate": "datum.serie == ''Gasolina: sem tributos'' ? 0 : datum.serie == ''Gasolina: sem federais, ICMS dentro'' ? 1 : datum.serie == ''Gasolina: ICMS'' ? 2 : datum.serie == ''Gasolina: PIS/Cofins'' ? 3 : datum.serie == ''Gasolina: CIDE'' ? 4 : 9",
      "as": "ordem"
    }
  ],
  "mark": {
    "type": "area",
    "interpolate": "step-after"
  },
  "encoding": {
    "x": {
      "field": "Mês",
      "type": "temporal",
      "timeUnit": "yearmonth",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "labelAlign": "left",
        "labelPadding": 6,
        "labelOverlap": "greedy"
      }
    },
    "y": {
      "field": "valor",
      "type": "quantitative",
      "stack": "zero",
      "title": "R$ por 100 km",
      "axis": {
        "format": "$,.0f",
        "tickCount": 5
      }
    },
    "color": {
      "field": "Parcela",
      "type": "nominal",
      "scale": {
        "domain": [
          "Sem tributos",
          "Sem federais (ICMS dentro)",
          "ICMS",
          "PIS/Cofins",
          "CIDE"
        ],
        "range": [
          "#E1DFDD",
          "#B3B0AD",
          "#F2C811",
          "#605E5C",
          "#252423"
        ]
      },
      "legend": {
        "orient": "top",
        "title": null,
        "direction": "horizontal",
        "columns": 3,
        "labelLimit": 220
      }
    },
    "order": {
      "field": "ordem",
      "type": "quantitative"
    },
    "tooltip": [
      {
        "field": "Mês",
        "type": "temporal",
        "timeUnit": "yearmonth",
        "title": "Mês",
        "format": "%b/%Y"
      },
      {
        "field": "Gasolina: sem tributos",
        "title": "Sem tributos (R$/100 km)",
        "format": "$,.2f"
      },
      {
        "field": "Gasolina: sem federais, ICMS dentro",
        "title": "Sem federais (ICMS dentro) (R$/100 km)",
        "format": "$,.2f"
      },
      {
        "field": "Gasolina: ICMS",
        "title": "ICMS (R$/100 km)",
        "format": "$,.2f"
      },
      {
        "field": "Gasolina: PIS/Cofins",
        "title": "PIS/Cofins (R$/100 km)",
        "format": "$,.2f"
      },
      {
        "field": "Gasolina: CIDE",
        "title": "CIDE (R$/100 km)",
        "format": "$,.2f"
      }
    ]
  }
}'
